const{chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');(async()=>{const b=await chromium.launch({executablePath:process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const p=await b.newPage({viewport:{width:1100,height:1200}}),results=[],errors=[];p.on('pageerror',e=>errors.push(String(e)));const out='docs/styles/style2/implementation/content-capacity';const cases=[];for(const layout of ['original','balanced','classic','oval'])for(const safeBottom of [0,34])cases.push({layout,safeBottom,scene:'squid-join',width:440,height:782});for(const [width,height]of [[440,782],[375,500],[320,400]])for(const scene of ['media-voice','media-video'])cases.push({layout:'original',width,height,scene});cases.push({layout:'original',width:844,height:440,orientation:'auto',scene:'squid-join'});
for(const c of cases){await p.goto((process.env.MX_AUDIT_URL||'http://127.0.0.1:5183')+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin:'style2',seats:8,action:1,bb:1,...c}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000});if(c.height<434)await p.locator('.mx-viewport').evaluate(e=>e.scrollTop=e.scrollHeight);const m=await p.evaluate(()=>{const rect=e=>{if(!e||!e.checkVisibility())return null;const r=e.getBoundingClientRect();return {left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height}};const intersects=(a,b)=>a&&b&&Math.min(a.right,b.right)-Math.max(a.left,b.left)>1&&Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top)>1;const quick=rect(document.querySelector('.mx-operation-quick')),info=rect(document.querySelector('.mx-seat-mine .mx-player-info')),join=rect(document.querySelector('.mx-squid-join')),logo=rect(document.querySelector('.mx-nav-logo')),nav=rect(document.querySelector('.mx-navigation')),buttons=[...document.querySelectorAll('.mx-nav-button')].map(rect);const own=[...document.querySelectorAll('.mx-seat-mine .mx-card-slot,.mx-seat-mine .mx-avatar,.mx-seat-mine .mx-player-info')].map(rect);const side=[];for(const edge of ['left','right']){const seats=[...document.querySelectorAll(`.mx-seat[data-edge=${edge}]`)].sort((a,b)=>a.getBoundingClientRect().top-b.getBoundingClientRect().top);for(let i=1;i<seats.length;i++){const prev=rect(seats[i-1].querySelector('.mx-seat-bet')),next=rect(seats[i].querySelector('.mx-player-action'));if(next&&prev&&intersects(prev,next))side.push({edge,index:i,prev,next})}}const identity=[...document.querySelectorAll('.mx-seat')].map(seat=>{const name=rect(seat.querySelector('.mx-player-name')),stack=rect(seat.querySelector('.mx-stack-slot')),bet=rect(seat.querySelector('.mx-seat-bet'));return {name,stack,bet,gap:name&&stack?stack.top-name.bottom:null,stackBetOverlap:intersects(stack,bet)}});return {identity,quick,info,join,logo,nav,buttons,heroQuickOverlap:intersects(info,quick),joinOverlap:!!join&&(intersects(join,quick)||own.some(r=>intersects(join,r))),logoOverlap:buttons.some(r=>intersects(logo,r)),sideOverlaps:side}});const failures=[];if(m.identity.some(x=>x.gap!==null&&x.gap<2.5))failures.push('name/balance gap too small');if(m.identity.some(x=>x.stackBetOverlap))failures.push('balance/bet overlap');if(m.heroQuickOverlap)failures.push('hero/quick overlap');if(m.joinOverlap)failures.push('join overlap');if(m.logoOverlap)failures.push('logo overlaps navigation');if(m.sideOverlaps.length)failures.push('side bet/action overlap');if(!c.orientation&&m.nav.height>65+(c.safeBottom||0))failures.push('footer too tall');if(m.buttons.some(x=>x.width<43.9||x.height<43.9))failures.push('navigation hit area');results.push({case:c,metrics:m,failures,errors:errors.splice(0)});await p.locator('#audit-stage').screenshot({path:`${out}/footer-${c.layout}-${c.scene}-${c.width}x${c.height}-safe${c.safeBottom||0}.png`});}
fs.writeFileSync(out+'/footer-results.json',JSON.stringify(results,null,2));console.log({cases:results.length,failures:results.filter(r=>r.failures.length||r.errors.length)});if(results.some(r=>r.failures.length||r.errors.length))process.exitCode=1;await b.close()})();
